const recover = async (fs: FsPort): Promise<string[]> => {
  const text = await fs.read(".journal");
  if (!text) return [];
  const entries = JSON.parse(text) as Array<{ txid: string }>;
  return entries.map((e) => e.txid);
};
const journal = await recover(ports.fs);
for (const entry of journal) {
  diagnostics.push({ code: "OARC-W094", detail: entry });
}
